// examples/12-crypto-fly/launch.ts
//
// Crypto Fly — Hill Climbing 自学习的果蝇大脑，用真实 Gate.io K 线做 paper trading。
//
// 启动：node --experimental-strip-types --no-warnings examples/12-crypto-fly/launch.ts [port]
//   port    默认 4322
//
// 数据源：Gate.io 公共 API（无需 API key）
//   pair    BTC_USDT  (默认)
//   interval 1h       (默认: 1h, 可选 5m/15m/4h/1d/...)
//   limit   1000      (默认: 1000 根 = 41 天)
//
// 学习算法：1+1-ES Hill Climbing（跟 11-screen-fly 完全相同）
//   - 每 epLen 根 candle 评估一个 challenger
//   - challenger = champion + 高斯噪声扰动
//   - P&L 比较：接受 / 拒绝
//   - sigma 衰减 = sigma0 * 0.96^gen（越学越精细）
//
// 用 simulator.state() 快照 + 恢复，让 challenger 评估不污染主循环的脑状态。

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, dirname, extname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawn } from 'node:child_process';
import {
  createTrainer,
  freshModel,
  cloneModel,
  inferReadout,
  type ReadoutModel,
  type Trainer,
} from '../../dist/index.js';

const here     = dirname(fileURLToPath(import.meta.url));
const ROOT     = here;
const fixDir   = resolve(here, '..', '..', 'fixtures');

// ---------- 1. Gate.io 公共 K 线接口 ----------
interface Candle {
  ts: number; open: number; high: number; low: number; close: number; volume: number;
}
async function fetchCandles(pair: string, interval: string, limit: number): Promise<Candle[]> {
  const url = `https://api.gateio.ws/api/v4/spot/candlesticks?currency_pair=${pair}&interval=${interval}&limit=${limit}`;
  console.log(`  GET ${url}`);
  const res = await fetch(url);
  if (!res.ok) throw new Error(`gate.io HTTP ${res.status}: ${await res.text()}`);
  const raw: string[][] = await res.json();
  // [ts, vol_quote, close, high, low, open, vol_base, is_closed]
  const candles: Candle[] = raw.map(r => ({
    ts:     +r[0],
    open:   +r[5],
    high:   +r[3],
    low:    +r[4],
    close:  +r[2],
    volume: +r[6],
  })).sort((a, b) => a.ts - b.ts);
  if (candles.length === 0) throw new Error('gate.io returned empty array');
  return candles;
}

// ---------- 2. OHLCV → 6 通道神经驱动（跟 09 一致） ----------
function encode(c: Candle, prev: Candle): Record<string, number> {
  const range  = c.high - c.low;
  const dnWick = Math.min(c.open, c.close) - c.low;
  const ret    = (c.close - prev.close) / Math.max(prev.close, 1e-9);
  const volChg = c.volume / Math.max(prev.volume, 1e-9);
  return {
    LC4_L:    Math.min(1, range  / Math.max(c.close, 1e-9) * 50),
    LPLC2_L:  Math.min(1, dnWick / Math.max(range,  1e-9) * 3),
    LC10a_L:  Math.min(1, Math.max(0, -ret * 50 + (volChg - 1) * 0.3)),
    LC10a_R:  Math.min(1, Math.max(0,  ret * 50 + (volChg - 1) * 0.3)),
    upward:   ret > 0 ? Math.min(1,  ret * 30) : 0,
    downward: ret < 0 ? Math.min(1, -ret * 30) : 0,
  };
}

// ---------- 3. Brain state 快照 / 恢复 ----------
function snapshot(sim: Trainer['simulator']) {
  const s = sim.state();
  return {
    v:           new Float32Array(s.v),
    activity:    new Uint8Array(s.activity),
    rng:         s.rng,
    traces:      new Float32Array(s.traces),
    totalSpikes: s.totalSpikes,
  };
}
function restore(sim: Trainer['simulator'], snap: ReturnType<typeof snapshot>) {
  const s = sim.state();
  s.v.set(snap.v);
  s.activity.set(snap.activity);
  s.rng = snap.rng;
  s.traces.set(snap.traces);
  s.totalSpikes = snap.totalSpikes;
  s.drive.fill(0);
  s.current.fill(0);
  s.firedCount = 0;
}

// ---------- 4. 蝇脑交易训练器 ----------
class FlyCrypto {
  trainer: Trainer;
  candles: Candle[] = [];
  idx = 1;             // 当前 candle 位置（>=1 因为要 prev）
  model:    ReadoutModel;      // champion
  challenger: ReadoutModel | null = null;
  gen = 0;
  sigma = 0.5;
  epLen = 30;           // 每代多少根 candle
  position = 0;         // 0=空仓 1=满仓
  entryPrice = 0;
  pnl = 0;
  bestPnl = -Infinity;
  accepts = 0;
  totalTries = 0;
  history: Array<{ gen: number; score: number; accepted: boolean }> = [];
  trades:   Array<{ ts: number; action: 'BUY'|'SELL'; price: number; profit?: number; idx: number }> = [];
  recentFeatures: number[] = Array(12).fill(0);
  recentDecision: 'BUY'|'SELL'|'HOLD' = 'HOLD';
  recentP = 0.5;
  running = false;

  constructor(trainer: Trainer) {
    this.trainer = trainer;
    this.model = freshModel(trainer.features);
  }

  loadCandles(candles: Candle[]) {
    this.candles = candles;
    this.idx = 1;
    // brain warm-up：跑前 80 根让它进入稳态
    const warmup = Math.min(80, candles.length - 1);
    for (let i = 1; i <= warmup; i++) {
      this.trainer.simulator.stimulate(encode(this.candles[i], this.candles[i - 1]));
      this.trainer.simulator.step();
      this.trainer.simulator.sampleFeatures();
    }
    this.idx = 1;
  }

  reset() {
    this.idx = 1;
    this.model = freshModel(this.trainer.features);
    this.challenger = null;
    this.gen = 0;
    this.sigma = 0.5;
    this.position = 0;
    this.entryPrice = 0;
    this.pnl = 0;
    this.bestPnl = -Infinity;
    this.accepts = 0;
    this.totalTries = 0;
    this.history = [];
    this.trades = [];
  }

  // 用某个 model 决策 + 模拟 paper trade（无副作用）
  private decide(model: ReadoutModel, candle: Candle) {
    this.trainer.simulator.stimulate(encode(candle, this.candles[this.idx - 1]));
    this.trainer.simulator.step();
    const { smoothed } = this.trainer.simulator.sampleFeatures();
    const p = inferReadout(smoothed, model);
    const decision: 'BUY'|'SELL'|'HOLD' =
      p > model.threshold + 0.10 ? 'BUY'  :
      p < model.threshold - 0.10 ? 'SELL' :
                                    'HOLD';
    return { p, decision, smoothed: Array.from(smoothed) };
  }

  // 主循环：跑 champion → paper trade
  step() {
    if (this.idx >= this.candles.length - 1) return null;
    const candle = this.candles[this.idx];
    const { p, decision, smoothed } = this.decide(this.model, candle);
    this.recentFeatures = smoothed;
    this.recentDecision = decision;
    this.recentP = p;

    // paper trade
    if (decision === 'BUY' && this.position === 0) {
      this.position = 1;
      this.entryPrice = candle.close;
      this.trades.push({ ts: candle.ts, action: 'BUY', price: candle.close, idx: this.idx });
    } else if (decision === 'SELL' && this.position === 1) {
      const profit = candle.close - this.entryPrice;
      this.pnl += profit;
      this.trades.push({ ts: candle.ts, action: 'SELL', price: candle.close, profit, idx: this.idx });
      this.position = 0;
    }

    // 每 epLen 根 candle 评估一次 challenger
    const localIdx = this.idx - 1;  // 从 1 开始算
    if (localIdx > 0 && localIdx % this.epLen === 0) {
      this.evaluateChallenger();
    }

    this.idx++;
    return {
      idx: this.idx,
      ts: candle.ts,
      close: candle.close,
      ret: (candle.close - this.candles[this.idx - 1].close) / this.candles[this.idx - 1].close,
      p,
      decision,
      position: this.position,
      pnl: this.pnl,
      gen: this.gen,
      sigma: this.sigma * Math.pow(0.96, this.gen),
    };
  }

  // Hill Climbing 评估（snapshot → 跑 challenger → restore）
  private evaluateChallenger() {
    this.totalTries++;
    const end = this.idx;
    const start = Math.max(1, end - this.epLen);

    const snap = snapshot(this.trainer.simulator);

    // 评估窗口里 champion 的 P&L
    const championPnl = this._simulatePnl(this.model, start, end);

    const curSigma = this.sigma * Math.pow(0.96, this.gen);

    if (this.challenger === null) {
      // 第一代：只创建 challenger，不比较（用来让 lastAcceptedScore 有参照）
      this.challenger = this._mutate(this.model, curSigma);
      this.challengerScore = this._simulatePnl(this.challenger, start, end);
      this.lastAcceptedScore = championPnl;
    } else {
      const challengerPnl = this._simulatePnl(this.challenger, start, end);
      if (challengerPnl > this.lastAcceptedScore) {
        // accept
        this.model = this.challenger;
        this.lastAcceptedScore = challengerPnl;
        this.pnl = challengerPnl;          // 同步主 P&L
        this.bestPnl = Math.max(this.bestPnl, challengerPnl);
        this.accepts++;
        this.gen++;
        this.history.push({ gen: this.gen, score: challengerPnl, accepted: true });
      } else {
        this.history.push({ gen: this.gen, score: challengerPnl, accepted: false });
      }
      this.challenger = this._mutate(this.model, curSigma);
    }

    restore(this.trainer.simulator, snap);
  }

  // 在 [start, end) 区间跑某个 model 算 P&L（无 paper trade 副作用）
  private _simulatePnl(model: ReadoutModel, start: number, end: number): number {
    let pnl = 0;
    let position = 0;
    let entryPrice = 0;
    for (let i = start; i < end; i++) {
      const c = this.candles[i];
      this.trainer.simulator.stimulate(encode(c, this.candles[i - 1]));
      this.trainer.simulator.step();
      const { smoothed } = this.trainer.simulator.sampleFeatures();
      const p = inferReadout(smoothed, model);
      const d =
        p > model.threshold + 0.10 ? 'BUY'  :
        p < model.threshold - 0.10 ? 'SELL' :
                                      'HOLD';
      if (d === 'BUY' && position === 0) {
        position = 1; entryPrice = c.close;
      } else if (d === 'SELL' && position === 1) {
        pnl += c.close - entryPrice;
        position = 0;
      }
    }
    if (position === 1) pnl += this.candles[end - 1].close - entryPrice;
    return pnl;
  }

  // 变异：跟 11 一致的 mutate 函数
  private _mutate(model: ReadoutModel, sigma: number): ReadoutModel {
    const m = cloneModel(model);
    for (let i = 0; i < m.weights.length; i++) {
      m.weights[i] += (Math.random() - 0.5) * 2 * sigma;
    }
    m.bias += (Math.random() - 0.5) * 2 * sigma * 0.4;
    m.threshold = Math.max(0.15, Math.min(0.85,
      m.threshold + (Math.random() - 0.5) * 2 * sigma * 0.15));
    return m;
  }

  getState() {
    return {
      candles: this.candles.length,
      idx: this.idx,
      pnl: this.pnl,
      bestPnl: this.bestPnl === -Infinity ? 0 : this.bestPnl,
      gen: this.gen,
      sigma: this.sigma * Math.pow(0.96, this.gen),
      accepts: this.accepts,
      totalTries: this.totalTries,
      position: this.position,
      entryPrice: this.entryPrice,
      history: this.history.slice(-100),
      trades: this.trades.slice(-20),
      recentP: this.recentP,
      recentDecision: this.recentDecision,
      features: this.recentFeatures,
      model: {
        bias: this.model.bias,
        threshold: this.model.threshold,
        weights: this.model.weights,
      },
      running: this.running,
      pair: process.argv[3] || 'BTC_USDT',
      interval: process.argv[4] || '1h',
    };
  }
}

// ---------- 5. 启动 ----------
const PORT     = parseInt(process.argv[2] || '4322', 10);
const PAIR     = process.argv[3] || 'BTC_USDT';
const INTERVAL = process.argv[4] || '1h';
const LIMIT    = parseInt(process.argv[5] || '1000', 10);
const STEP_MS  = parseInt(process.env.STEP_MS || '200', 10);

const manifest = JSON.parse(
  await readFile(resolve(fixDir, 'brain.json'), 'utf-8'),
);
console.log(`brain: ${manifest.neurons.toLocaleString()} neurons, ${manifest.connections.toLocaleString()} connections`);

const trainer = await createTrainer({
  metaPath:     resolve(fixDir, 'meta.bin'),
  weightsPaths: [
    resolve(fixDir, 'weights.0.bin'),
    resolve(fixDir, 'weights.1.bin'),
  ],
  manifest,
  seed: 42,
});

const fly = new FlyCrypto(trainer);

console.log(`fetching ${LIMIT} ${INTERVAL} K-lines (${PAIR}) from gate.io ...`);
const candles = await fetchCandles(PAIR, INTERVAL, LIMIT);
console.log(`  loaded ${candles.length} candles`);
console.log(`  range: ${new Date(candles[0].ts * 1000).toISOString()} → ${new Date(candles[candles.length - 1].ts * 1000).toISOString()}`);
console.log(`  price: ${candles[0].close.toFixed(0)} → ${candles[candles.length - 1].close.toFixed(0)} (${(((candles[candles.length - 1].close / candles[0].close) - 1) * 100).toFixed(1)}%)`);
fly.loadCandles(candles);
console.log('brain warm-up done.\n');

// ---------- 6. 主循环 ----------
let timer: NodeJS.Timeout | null = null;
function tick() {
  if (fly.idx >= fly.candles.length - 1) {
    console.log('\n[fly] all candles consumed. press reset to replay.');
    if (timer) { clearInterval(timer); timer = null; }
    fly.running = false;
    return;
  }
  const r = fly.step();
  if (r && fly.gen % 5 === 0 && r.gen > 0) {
    process.stdout.write(`\r[fly] idx=${r.idx}/${fly.candles.length}  pnl=${r.pnl >= 0 ? '+' : ''}${r.pnl.toFixed(0)}  gen=${r.gen}  acc=${fly.accepts}/${fly.totalTries}  p=${r.p.toFixed(2)} → ${r.decision}    `);
  }
}
function start() {
  if (timer) return;
  fly.running = true;
  timer = setInterval(tick, STEP_MS);
}
function stop() {
  if (timer) { clearInterval(timer); timer = null; }
  fly.running = false;
}

// ---------- 7. HTTP server ----------
const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js':   'application/javascript; charset=utf-8',
  '.css':  'text/css; charset=utf-8',
  '.json': 'application/json',
  '.png':  'image/png',
};

const server = createServer(async (req, res) => {
  const url = req.url || '/';
  const [path] = url.split('?');

  // ---- API ----
  if (path === '/api/state') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(fly.getState()));
    return;
  }
  if (path === '/api/candles') {
    // 只返回前 fly.idx + 200 根（避免传 1000 根到浏览器）
    const from = Math.max(0, fly.idx - 200);
    const slice = fly.candles.slice(from, Math.min(fly.candles.length, fly.idx + 1));
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ candles: slice, from, currentIdx: fly.idx }));
    return;
  }
  if (path === '/api/start')   { start(); res.writeHead(200); res.end('started');  return; }
  if (path === '/api/pause')   { stop();  res.writeHead(200); res.end('paused');   return; }
  if (path === '/api/reset')   {
    stop();
    fly.reset();
    fly.loadCandles(candles);
    start();
    res.writeHead(200); res.end('reset'); return;
  }

  // ---- 静态文件 ----
  let filePath = path === '/' ? '/index.html' : path;
  const fp = join(ROOT, filePath);
  try {
    const body = await readFile(fp);
    res.writeHead(200, { 'Content-Type': MIME[extname(fp)] || 'application/octet-stream' });
    res.end(body);
  } catch {
    res.writeHead(404); res.end('not found');
  }
});

server.listen(PORT, '127.0.0.1', () => {
  const url = `http://127.0.0.1:${PORT}/`;
  console.log(`\nfly-server: ${url}`);
  console.log(`  open in browser to see crypto fly learning.`);
  console.log(`  pair=${PAIR}  interval=${INTERVAL}  candles=${candles.length}  step=${STEP_MS}ms`);
  console.log(`  ctrl+C to quit.\n`);
  start();

  const opener =
    process.platform === 'win32'  ? `start "" "${url}"` :
    process.platform === 'darwin' ? `open "${url}"` :
                                    `xdg-open "${url}"`;
  spawn(opener, { shell: true, stdio: 'ignore', windowsHide: true });
});

process.on('SIGINT',  () => { stop(); server.close(); process.exit(0); });
process.on('SIGTERM', () => { stop(); server.close(); process.exit(0); });"}

