<script>
'use strict';

// ---------- DOM 引用 ----------
const $ = id => document.getElementById(id);
const dom = {
  pair: $('pair'), interval: $('interval'),
  idx: $('idx'), total: $('total'),
  price: $('price'), ret: $('ret'), p: $('p'),
  decision: $('decision'), pos: $('pos'), entry: $('entry'), unrealized: $('unrealized'),
  pnlBig: $('pnlBig'), bestPnl: $('bestPnl'),
  gen: $('gen'), sigma: $('sigma'),
  accepts: $('accepts'), tries: $('tries'), accRate: $('accRate'),
  features: $('features'), weights: $('weights'),
  trades: $('trades'),
  btnPause: $('btnPause'), btnReset: $('btnReset'), btnStart: $('btnStart'),
};
const chart    = $('chart').getContext('2d');
const pnlChart = $('pnlChart').getContext('2d');
const learnChart = $('learnChart').getContext('2d');

// ---------- 初始化 12 个 feature bar ----------
const FEATURE_NAMES = [
  'TARGET_DN L','TARGET_DN R',
  'LOOM_DN L','LOOM_DN R',
  'ESCAPE_DN L','ESCAPE_DN R',
  'DNae002 L','DNae002 R',
  'DNg111 L','DNg111 R',
  'DNp01 L','DNp01 R',
];
const featBars = [];
FEATURE_NAMES.forEach((n, i) => {
  const row = document.createElement('div');
  row.className = 'feat-bar';
  row.innerHTML = `<div class="name">${n}</div><div class="bar"><div class="fill" id="fb${i}"></div></div><div class="v" id="fv${i}">0.00</div>`;
  dom.features.appendChild(row);
  featBars.push({ fill: $('fb'+i), v: $('fv'+i) });
});

// ---------- 权重条形图 ----------
const weightBars = [];
FEATURE_NAMES.forEach((n, i) => {
  const row = document.createElement('div');
  row.className = 'feat-bar';
  row.innerHTML = `<div class="name" style="color:#6f6;">${n}</div><div class="bar"><div class="fill" id="wb${i}" style="background:linear-gradient(90deg,#f55,#5f5,#ff6); transform-origin: left;"></div></div><div class="v" id="wv${i}">+0.00</div>`;
  dom.weights.appendChild(row);
  weightBars.push({ fill: $('wb'+i), v: $('wv'+i) });
});

// ---------- 全局状态 ----------
let candles = [];
let candleFrom = 0;
let state = null;
let lastPnlTrace = [];
let lastUpdate = 0;

// ---------- 轮询 ----------
async function fetchState() {
  const r = await fetch('/api/state');
  state = await r.json();
}
async function fetchCandles() {
  const r = await fetch('/api/candles');
  const j = await r.json();
  candles = j.candles;
  candleFrom = j.from;
}

async function tick() {
  await fetchState();
  if (candles.length === 0) await fetchCandles();
  await fetchCandles();
  drawAll();
}

setInterval(tick, 250);

// ---------- 绘图 ----------
function fmtUSD(n) {
  const sign = n >= 0 ? '+' : '-';
  return sign + '$' + Math.abs(n).toFixed(0);
}
function fmtPct(n) {
  const sign = n >= 0 ? '+' : '';
  return sign + (n * 100).toFixed(2) + '%';
}

function drawChart() {
  const c = $('chart');
  const W = c.width, H = c.height;
  chart.clearRect(0, 0, W, H);

  if (candles.length === 0) return;

  // 价格范围
  let pMin = Infinity, pMax = -Infinity;
  for (const k of candles) {
    if (k.low < pMin)  pMin = k.low;
    if (k.high > pMax) pMax = k.high;
  }
  const pad = (pMax - pMin) * 0.05;
  pMin -= pad; pMax += pad;

  // 蜡烛宽度
  const N = candles.length;
  const cw = Math.max(2, Math.floor(W / N) - 1);
  const ch = H - 30;

  const yOf = p => 20 + ch - (p - pMin) / (pMax - pMin) * ch;

  // 网格
  chart.strokeStyle = '#222';
  chart.lineWidth = 1;
  for (let i = 0; i <= 4; i++) {
    const y = 20 + ch * i / 4;
    chart.beginPath(); chart.moveTo(0, y); chart.lineTo(W, y); chart.stroke();
    const p = pMin + (pMax - pMin) * (4 - i) / 4;
    chart.fillStyle = '#666'; chart.font = '10px monospace';
    chart.fillText('$' + p.toFixed(0), 4, y - 2);
  }

  // 蜡烛
  for (let i = 0; i < N; i++) {
    const k = candles[i];
    const x = i * (cw + 1);
    const isUp = k.close >= k.open;
    chart.strokeStyle = isUp ? '#5f5' : '#f55';
    chart.fillStyle   = isUp ? '#0a0' : '#a00';

    // wick
    chart.beginPath();
    chart.moveTo(x + cw / 2, yOf(k.high));
    chart.lineTo(x + cw / 2, yOf(k.low));
    chart.stroke();

    // body
    const y1 = yOf(Math.max(k.open, k.close));
    const y2 = yOf(Math.min(k.open, k.close));
    chart.fillRect(x, y1, cw, Math.max(1, y2 - y1));
  }

  // 当前 candle 高亮
  const curIdx = state.idx - candleFrom;
  if (curIdx >= 0 && curIdx < N) {
    const x = curIdx * (cw + 1);
    chart.strokeStyle = '#ff6';
    chart.lineWidth = 2;
    chart.strokeRect(x - 1, 20, cw + 2, ch);
  }

  // 🪰 苍蝇位置：12 features → 2D (用 L/R 加权求和模拟"水平位置"和"垂直位置")
  const f = state.features || new Array(12).fill(0);
  let leftEnergy = 0, rightEnergy = 0, topEnergy = 0, botEnergy = 0;
  // L/R 加权
  for (let i = 0; i < 12; i += 2) {
    leftEnergy  += f[i];
    rightEnergy += f[i+1];
  }
  // 上/下 用 LC4(0-1) vs LPLC2(2-3) 简单划分
  topEnergy = (f[0] + f[2] + f[4]) / 3;
  botEnergy = (f[6] + f[8] + f[10]) / 11 * 11 / 3;

  const fx = (rightEnergy - leftEnergy) * 0.5 + 0.5;  // 0..1
  const fy = (topEnergy - botEnergy) * 0.5 + 0.5;

  const flyX = fx * W;
  const flyY = fy * (ch) + 20;

  // 画苍蝇（emoji 不行用十字）
  chart.fillStyle = '#ff6';
  chart.beginPath(); chart.arc(flyX, flyY, 7, 0, Math.PI * 2); chart.fill();
  chart.strokeStyle = '#000';
  chart.lineWidth = 2;
  chart.beginPath();
  chart.moveTo(flyX - 12, flyY); chart.lineTo(flyX + 12, flyY);
  chart.moveTo(flyX, flyY - 12); chart.lineTo(flyX, flyY + 12);
  chart.stroke();
  chart.fillStyle = '#000';
  chart.font = 'bold 10px monospace';
  chart.fillText('FLY', flyX - 12, flyY + 3);

  // 标题
  chart.fillStyle = '#ff6'; chart.font = 'bold 12px monospace';
  chart.fillText(`${state.pair} ${state.interval}  idx=${state.idx}/${state.candles}  close=$${state && candles[curIdx] ? candles[curIdx].close.toFixed(0) : '-'}`, 8, H - 6);
}

function drawPnlChart() {
  const c = $('pnlChart');
  const W = c.width, H = c.height;
  pnlChart.clearRect(0, 0, W, H);

  // 用 trades 累积 P&L
  const points = [{ idx: 0, pnl: 0 }];
  let cum = 0;
  for (const t of state.trades) {
    if (t.action === 'SELL' && typeof t.profit === 'number') {
      cum += t.profit;
      points.push({ idx: t.idx, pnl: cum });
    }
  }
  // 加上当前未实现（如果持仓）
  if (state.position === 1 && state.entryPrice && candles.length > 0) {
    const lastClose = candles[Math.min(candles.length - 1, state.idx - candleFrom)]?.close ?? state.entryPrice;
    points.push({ idx: state.idx, pnl: cum + (lastClose - state.entryPrice) });
  }

  if (points.length < 2) {
    pnlChart.fillStyle = '#666'; pnlChart.font = '12px monospace';
    pnlChart.fillText('等待交易...', 10, H / 2);
    return;
  }

  const xMin = 0, xMax = state.candles;
  let yMin = 0, yMax = 0;
  for (const p of points) { yMin = Math.min(yMin, p.pnl); yMax = Math.max(yMax, p.pnl); }
  const yRange = Math.max(100, yMax - yMin) * 1.2;
  const yMid = (yMax + yMin) / 2;
  yMin = yMid - yRange / 2; yMax = yMid + yRange / 2;

  const xOf = i => (i - xMin) / (xMax - xMin) * W;
  const yOf = v => H - (v - yMin) / (yMax - yMin) * (H - 20) - 10;

  // 网格 + 0 线
  pnlChart.strokeStyle = '#222'; pnlChart.lineWidth = 1;
  pnlChart.beginPath();
  pnlChart.moveTo(0, yOf(0)); pnlChart.lineTo(W, yOf(0));
  pnlChart.stroke();
  pnlChart.fillStyle = '#888'; pnlChart.font = '10px monospace';
  pnlChart.fillText(`+$${(yMax).toFixed(0)}`, 4, 12);
  pnlChart.fillText(` $${(yMin).toFixed(0)}`, 4, H - 4);

  // 曲线
  pnlChart.strokeStyle = '#ff6'; pnlChart.lineWidth = 2;
  pnlChart.beginPath();
  pnlChart.moveTo(xOf(points[0].idx), yOf(points[0].pnl));
  for (const p of points) pnlChart.lineTo(xOf(p.idx), yOf(p.pnl));
  pnlChart.stroke();

  // 当前点
  const last = points[points.length - 1];
  pnlChart.fillStyle = last.pnl >= 0 ? '#5f5' : '#f55';
  pnlChart.beginPath(); pnlChart.arc(xOf(last.idx), yOf(last.pnl), 5, 0, Math.PI * 2); pnlChart.fill();
}

function drawLearnChart() {
  const c = $('learnChart');
  const W = c.width, H = c.height;
  learnChart.clearRect(0, 0, W, H);

  const hist = state.history || [];
  if (hist.length < 1) {
    learnChart.fillStyle = '#666'; learnChart.font = '12px monospace';
    learnChart.fillText('等待 challenger 评估...', 10, H / 2);
    return;
  }

  // x: gen, y: score (P&L of last 30 candles)
  let yMin = 0, yMax = 0;
  for (const h of hist) { yMin = Math.min(yMin, h.score); yMax = Math.max(yMax, h.score); }
  const yRange = Math.max(100, yMax - yMin) * 1.2;
  const yMid = (yMax + yMin) / 2;
  yMin = yMid - yRange / 2; yMax = yMid + yRange / 2;
  const xMax = Math.max(state.gen, hist.length);

  const xOf = g => g / xMax * W;
  const yOf = v => H - (v - yMin) / (yMax - yMin) * (H - 20) - 10;

  // 网格
  learnChart.strokeStyle = '#222'; learnChart.lineWidth = 1;
  learnChart.beginPath();
  learnChart.moveTo(0, yOf(0)); learnChart.lineTo(W, yOf(0));
  learnChart.stroke();

  // 接受 (绿) / 拒绝 (红)
  for (let i = 0; i < hist.length; i++) {
    const h = hist[i];
    learnChart.fillStyle = h.accepted ? '#5f5' : '#a55';
    learnChart.beginPath();
    learnChart.arc(xOf(h.gen), yOf(h.score), 4, 0, Math.PI * 2);
    learnChart.fill();
  }

  // bestPnl 折线
  let best = -Infinity;
  const bestLine = [];
  for (const h of hist) {
    if (h.accepted) { best = Math.max(best, h.score); }
    bestLine.push({ gen: h.gen, v: best === -Infinity ? 0 : best });
  }
  if (bestLine.length > 1) {
    learnChart.strokeStyle = '#ff6'; learnChart.lineWidth = 2;
    learnChart.beginPath();
    learnChart.moveTo(xOf(bestLine[0].gen), yOf(bestLine[0].v));
    for (const p of bestLine) learnChart.lineTo(xOf(p.gen), yOf(p.v));
    learnChart.stroke();
  }
}

function drawTrades() {
  const trades = state.trades.slice(-10).reverse();
  if (trades.length === 0) {
    dom.trades.innerHTML = '<div style="color:#666;">尚未交易</div>';
    return;
  }
  const rows = trades.map(t => {
    const dt = new Date(t.ts * 1000);
    const time = `${dt.getMonth()+1}/${dt.getDate()} ${String(dt.getHours()).padStart(2,'0')}:00`;
    if (t.action === 'BUY') {
      return `<div><span style="color:#5f5">▶ BUY </span> @ $${t.price.toFixed(0)} (${time})</div>`;
    } else {
      const cls = t.profit >= 0 ? 'pnl-pos' : 'pnl-neg';
      return `<div><span style="color:#f55">◀ SELL</span> @ $${t.price.toFixed(0)} (${time})  <span class="${cls}">${t.profit >= 0 ? '+' : ''}$${t.profit.toFixed(0)}</span></div>`;
    }
  });
  dom.trades.innerHTML = rows.join('');
}

function drawAll() {
  if (!state) return;

  // HUD
  dom.pair.textContent = state.pair;
  dom.interval.textContent = state.interval;
  dom.idx.textContent = state.idx;
  dom.total.textContent = state.candles;
  const curIdx = state.idx - candleFrom;
  const curCandle = candles[curIdx] || candles[candles.length - 1];
  if (curCandle) {
    dom.price.textContent = '$' + curCandle.close.toFixed(0);
    const prev = candles[curIdx - 1];
    if (prev) {
      const ret = (curCandle.close - prev.close) / prev.close;
      dom.ret.textContent = fmtPct(ret);
      dom.ret.style.color = ret >= 0 ? '#5f5' : '#f55';
    }
  }
  dom.p.textContent = state.recentP.toFixed(3);
  dom.p.style.color = state.recentP > 0.5 ? '#5f5' : '#f55';

  // Decision badge
  dom.decision.textContent = state.recentDecision;
  dom.decision.className = 'badge ' + state.recentDecision;

  // Position
  if (state.position === 1) {
    dom.pos.innerHTML = '<span class="pos-long">满仓 LONG</span>';
    dom.entry.textContent = '$' + state.entryPrice.toFixed(0);
    if (curCandle) {
      const unreal = curCandle.close - state.entryPrice;
      dom.unrealized.textContent = fmtUSD(unreal);
      dom.unrealized.style.color = unreal >= 0 ? '#5f5' : '#f55';
    }
  } else {
    dom.pos.innerHTML = '<span class="pos-flat">空仓</span>';
    dom.entry.textContent = '-';
    dom.unrealized.textContent = '-';
  }

  // P&L
  const pnlClass = state.pnl >= 0 ? 'pnl-pos' : 'pnl-neg';
  dom.pnlBig.className = 'v ' + pnlClass;
  dom.pnlBig.textContent = fmtUSD(state.pnl);
  dom.bestPnl.textContent = fmtUSD(state.bestPnl);
  dom.gen.textContent = state.gen;
  dom.sigma.textContent = state.sigma.toFixed(3);
  dom.accepts.textContent = state.accepts;
  dom.tries.textContent = state.totalTries;
  dom.accRate.textContent = state.totalTries > 0 ? Math.round(state.accepts / state.totalTries * 100) + '%' : '0%';

  // Features
  for (let i = 0; i < 12; i++) {
    const v = state.features[i] || 0;
    featBars[i].fill.style.width = Math.min(100, v * 100).toFixed(1) + '%';
    featBars[i].v.textContent = v.toFixed(2);
  }

  // Weights
  const w = state.model.weights;
  const wMin = Math.min(...w);
  const wMax = Math.max(...w);
  const wAbsMax = Math.max(Math.abs(wMin), Math.abs(wMax), 0.01);
  for (let i = 0; i < 12; i++) {
    const v = w[i];
    // map [-wAbsMax, wAbsMax] → [0, 100%], center at 50%
    const pct = ((v + wAbsMax) / (2 * wAbsMax)) * 100;
    weightBars[i].fill.style.width = pct.toFixed(1) + '%';
    weightBars[i].v.textContent = (v >= 0 ? '+' : '') + v.toFixed(3);
    weightBars[i].v.style.color = v >= 0 ? '#5f5' : '#f55';
  }

  drawChart();
  drawPnlChart();
  drawLearnChart();
  drawTrades();
}

// ---------- 按钮 ----------
dom.btnPause.onclick = async () => { await fetch('/api/pause'); };
dom.btnStart.onclick = async () => { await fetch('/api/start'); };
dom.btnReset.onclick = async () => { await fetch('/api/reset'); };

// 启动
tick();
</script>
</body>
